-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_EMS_MRRS_MSN_OSTD_DEBT
SELECT DISTINCT SYS_RPT_YEAR, SYS_RPT_MTH FROM SOR_EMS_MRRS_MSN_OSTD_DEBT 
WHERE (SYS_RPT_YEAR=TO_NUMBER(SUBSTR('$$EMM_MRRS_RENT_CUTOFF',1,4)) AND SYS_RPT_MTH>TO_NUMBER(SUBSTR('$$EMM_MRRS_RENT_CUTOFF',5,2)))
