SELECT sts.CUST_ACCC_PYMT_KEY as CUST_ACCC_PYMT_KEY, sts.BGN_DATE as BGN_DATE, sts.END_DATE as END_DATE, 
sts.CUST_KEY as CUST_KEY, sts.HSE_SRVC_APLY_KEY as HSE_SRVC_APLY_KEY, 
sts.ACCC_TXN_INTF_INPT_DATE as ACCC_TXN_INTF_INPT_DATE, sts.ACCC_TXN_INTF_PRCS_DATE as ACCC_TXN_INTF_PRCS_DATE, 
