sts.CUST_ACCC_TXN_CHQ_DTL_TEXT as CUST_ACCC_TXN_CHQ_DTL_TEXT, 
sts.CUST_ACCC_TXN_PRCS_DATE as CUST_ACCC_TXN_PRCS_DATE, 
sts.CUST_ACCC_TXN_PRCS_STS_CODE as CUST_ACCC_TXN_PRCS_STS_CODE, 
sts.LAST_CUST_ACCC_TXN_UPD_DATE as LAST_CUST_ACCC_TXN_UPD_DATE, 
sts.CUST_PYB_ITEM_KEY as CUST_PYB_ITEM_KEY, sts.CUST_PYB_ITEM_COST_CTR_CODE as CUST_PYB_ITEM_COST_CTR_CODE, 
