-- [SOURCE_QUALIFIER] Step: apply_SQ_EMS_HSM_UNIT_SCND_ENV_CODE
SELECT HSE_UNIT_KEY as HSE_UNIT_KEY, UNIT_SCND_ENV_CODE as UNIT_SCND_ENV_CODE, UNIT_SCND_ENV_CODE_BGN_DATE as UNIT_SCND_ENV_CODE_BGN_DATE, UNIT_SCND_ENV_CODE_END_DATE as UNIT_SCND_ENV_CODE_END_DATE, LAST_REC_TXN_TYPE_CODE as LAST_REC_TXN_TYPE_CODE, LAST_REC_TXN_DATE as LAST_REC_TXN_DATE, LAST_REC_TXN_USER_ID as LAST_REC_TXN_USER_ID, UNIT_SCND_ENV_CODE_EXTN_IND as UNIT_SCND_ENV_CODE_EXTN_IND 

FROM EMS_HSM_UNIT_SCND_ENV_CODE;

-- [SOURCE_QUALIFIER] Step: apply_SQ_EMS_HSM_UNIT_SCND_ENV_END
select k.unit_scnd_env_key, ks.bgn_date
from sor_ems_hsm_unit_scnd_env k, sor_ems_hsm_unit_scnd_env_sts ks left join 
(select /*+ ordered */ k.unit_scnd_env_key from ems_hsm_unit_scnd_env_code p, sor_hsm_unit a, sor_ems_hsm_unit_scnd_env k
where p.hse_unit_key = a.emms_unit_key
  and k.unit_key = a.unit_key
  and p.unit_scnd_env_code = k.unit_scnd_env_code
  and (p.unit_scnd_env_code_bgn_date = k.unit_scnd_env_code_bgn_date or (p.unit_scnd_env_code_bgn_date is null and k.unit_scnd_env_code_bgn_date is null))
  and (p.unit_scnd_env_code_end_date = k.unit_scnd_env_code_end_date or (p.unit_scnd_env_code_end_date is null and k.unit_scnd_env_code_end_date is null))
) e
on ks.unit_scnd_env_key = e.unit_scnd_env_key
where k.unit_scnd_env_key = ks.unit_scnd_env_key and ks.end_date = date'9999-12-31'
and e.unit_scnd_env_key is null
and exists (select 1 from ems_hsm_unit_scnd_env_code);

